// ─────────────────────────────────────────────────────────────────────
// Node: Verify Secret & Normalize Event      Mode: Run Once for All Items
// Repo: n8n-connecteam-field-checklist-hubspot-deal-updater · dhRobin Systems
// Authentication (fails closed):
//   header_secret (default) Connecteam sends the webhook's secretKey verbatim
//                           in `x-webhook-secret`; compared in constant time.
//   hmac_sha256             For deliveries re-signed by a gateway/relay:
//                           HMAC-SHA256(raw body) in CONNECTEAM_SIGNATURE_HEADER.
// Then: only configured checklist forms, only processed event types, and
// each formSubmissionId at most once (retries and duplicates are ignored).
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const helpers = this.helpers;
let crypto = null;
try { crypto = require('crypto'); } catch (error) { crypto = null; }

const SANDBOX_MODE = flag('SANDBOX_MODE', true);
const DRY_RUN = flag('DRY_RUN', true);
const PERSIST = !SANDBOX_MODE && !DRY_RUN;
const AUTH_MODE = env('CONNECTEAM_AUTH_MODE', 'header_secret').toLowerCase();
const SECRET_HEADER = env('CONNECTEAM_SECRET_HEADER', 'x-webhook-secret').toLowerCase();
const SIG_HEADER = env('CONNECTEAM_SIGNATURE_HEADER', 'x-signature').toLowerCase();
const SANDBOX_SECRET = 'sandbox-fictional-connecteam-secret-not-for-production';
const SECRET = env('CONNECTEAM_WEBHOOK_SECRET', '') || (SANDBOX_MODE ? SANDBOX_SECRET : '');
const EVENT_TYPES = new Set(csv('PROCESS_EVENT_TYPES', 'form_submission'));
const YES_INDEX = num('YES_NO_YES_INDEX', 0);
const DEDUPE_DAYS = Math.max(1, num('SUBMISSION_LEDGER_DAYS', 30));

let runId;
try { runId = 'chk_' + crypto.randomUUID(); } catch (error) { runId = 'chk_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8); }
const run = { runId, startedAt: new Date().toISOString(), mode: SANDBOX_MODE ? 'sandbox' : DRY_RUN ? 'dry_run' : 'live', sandboxMode: SANDBOX_MODE, dryRun: DRY_RUN };

const items = $input.all();
const sharedFixtures = SANDBOX_MODE ? (items.find((i) => i.json.sandboxFixtures) || { json: {} }).json.sandboxFixtures || null : null;

let FORMS = {};
try { FORMS = JSON.parse(env('CHECKLIST_FORMS_JSON', '')) || {}; } catch (e) { FORMS = {}; }
if (SANDBOX_MODE && !Object.keys(FORMS).length && sharedFixtures) FORMS = sharedFixtures.formConfig || {};

const sha = (s) => crypto.createHash('sha256').update(String(s)).digest();
const safeEqual = (a, b) => !!crypto && typeof a === 'string' && typeof b === 'string' && a.length > 0 && b.length > 0 && crypto.timingSafeEqual(sha(a), sha(b));

function authenticate(headers, raw) {
  if (!SECRET) return { ok: false, reason: 'webhook_secret_not_configured' };
  if (!crypto) return { ok: false, reason: 'crypto_module_unavailable' };
  if (AUTH_MODE === 'hmac_sha256') {
    const provided = String(headers[SIG_HEADER] || '').replace(/^sha256=/i, '');
    const mac = crypto.createHmac('sha256', SECRET).update(raw, 'utf8');
    const digest = mac.digest();
    const ok = safeEqual(provided, digest.toString('hex')) || safeEqual(provided, digest.toString('base64'));
    return ok ? { ok: true, method: 'hmac_sha256' } : { ok: false, method: 'hmac_sha256', reason: provided ? 'signature_mismatch' : 'signature_header_missing' };
  }
  const provided = headers[SECRET_HEADER] || '';
  if (!provided) return { ok: false, method: 'header_secret', reason: 'secret_header_missing' };
  return safeEqual(provided, SECRET) ? { ok: true, method: 'header_secret' } : { ok: false, method: 'header_secret', reason: 'secret_mismatch' };
}

const toMs = (v) => { const n = Number(v); return Number.isFinite(n) && n > 0 ? (n < 1e12 ? n * 1000 : n) : null; };
const MEDIA_KIND = { signature: 'signature', image: 'photo', scanDocument: 'scan', video: 'video', audioRecording: 'audio', files: 'file' };

function normalizeAnswer(a, prefix = '') {
  if (!a || typeof a !== 'object') return [];
  const type = String(a.questionType || 'unknown');
  const base = { questionId: String(a.questionId ?? ''), questionType: type, path: prefix, hidden: !!a.wasHidden, empty: !!a.wasSubmittedEmpty, hasLocation: !!a.location, value: null, positive: null, media: [] };
  switch (type) {
    case 'group':
      return (a.answers || []).flatMap((x) => normalizeAnswer(x, `${prefix}${base.questionId}/`));
    case 'multiGroup':
      return (a.groupAnswers || []).flatMap((g, i) => (Array.isArray(g) ? g : (g && g.answers) || []).flatMap((x) => normalizeAnswer(x, `${prefix}${base.questionId}#${i + 1}/`)));
    case 'description':
      return [];
    case 'multipleChoice': case 'imageSelection': case 'dropdown':
      base.value = (a.selectedAnswers || []).map((s) => s && (s.text ?? s.label)).filter(Boolean).join(', ') || null; break;
    case 'yesNo':
      if (Number.isInteger(a.selectedIndex)) { base.positive = a.selectedIndex === YES_INDEX; base.value = base.positive ? 'Yes' : 'No'; } break;
    case 'task':
      if (typeof a.isChecked === 'boolean') { base.positive = a.isChecked; base.value = a.isChecked ? 'Done' : 'Not done'; } break;
    case 'openEnded': case 'emailAddress': case 'phoneNumber':
      base.value = a.value != null && String(a.value).trim() !== '' ? String(a.value).trim().slice(0, 2000) : null; break;
    case 'number': base.value = a.inputValue != null ? String(a.inputValue) : null; break;
    case 'rating': base.value = a.ratingValue != null ? String(a.ratingValue) : null; break;
    case 'slider': base.value = a.value != null ? String(a.value) : null; break;
    case 'formula': base.value = a.result != null ? String(a.result) : null; break;
    case 'datetime': base.value = toMs(a.timestamp) ? new Date(toMs(a.timestamp)).toISOString() : null; base.timezone = a.timezone || null; break;
    case 'location': base.value = a.locationInput && a.locationInput.address ? String(a.locationInput.address).slice(0, 300) : null; break;
    case 'signature': case 'image': case 'scanDocument':
      base.media = (a.images || []).filter((m) => m && m.url).map((m, i) => ({ kind: MEDIA_KIND[type], url: String(m.url), name: `${MEDIA_KIND[type]}-${i + 1}` })); break;
    case 'video': base.media = (a.videos || []).filter((m) => m && m.videoUrl).map((m, i) => ({ kind: 'video', url: String(m.videoUrl), name: `video-${i + 1}` })); break;
    case 'audioRecording': base.media = a.audioUrl ? [{ kind: 'audio', url: String(a.audioUrl), name: 'audio-1', lengthSec: a.audioLength || null }] : []; break;
    case 'files': base.media = (a.files || []).filter((m) => m && m.url).map((m) => ({ kind: 'file', url: String(m.url), name: String(m.fileName || 'file').slice(0, 120), size: m.size || null })); break;
    default: base.value = a.value != null ? String(a.value).slice(0, 500) : null;
  }
  if (base.media.length) base.value = `${base.media.length} ${base.media[0].kind}${base.media.length === 1 ? '' : 's'}`;
  return [base];
}

const staticData = $getWorkflowStaticData('global');
const ledgerStore = PERSIST ? (staticData.ctChecklistLedger = staticData.ctChecklistLedger || {}) : JSON.parse(JSON.stringify(staticData.ctChecklistLedger || {}));
const nowMs = Date.now();
for (const [k, v] of Object.entries(ledgerStore)) if (!v || nowMs - v.at > DEDUPE_DAYS * 86400000) delete ledgerStore[k];
const seenThisRun = new Set();

const out = [];
for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const headers = {};
  for (const [k, v] of Object.entries(item.json.headers || {})) headers[String(k).toLowerCase()] = Array.isArray(v) ? String(v[0]) : String(v);
  let raw = null;
  if (item.binary && item.binary.data) { try { raw = (await helpers.getBinaryDataBuffer(index, 'data')).toString('utf8'); } catch (e) { raw = null; } }
  let body = item.json.body;
  if ((!body || (typeof body === 'object' && !Object.keys(body).length)) && raw) { try { body = JSON.parse(raw); } catch (e) { body = null; } }
  if (raw === null) raw = typeof body === 'string' ? body : JSON.stringify(body ?? {});
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }

  const base = { run, sandboxFixtures: sharedFixtures };
  const auth = authenticate(headers, raw);
  if (!auth.ok) { out.push({ json: { ...base, kind: 'rejected', reason: auth.reason, authMethod: auth.method || AUTH_MODE } }); continue; }

  const b = body && typeof body === 'object' ? body : {};
  const d = b.data || {};
  const ignore = (reason) => out.push({ json: { ...base, kind: 'ignored', reason, authMethod: auth.method, event: { requestId: b.requestId || null, eventType: b.eventType || null, formId: d.formId ?? null, submissionId: d.formSubmissionId || null } } });

  if (b.activityType !== 'forms') { ignore('not_a_forms_event'); continue; }
  if (!EVENT_TYPES.has(String(b.eventType))) { ignore('event_type_not_processed'); continue; }
  const formCfg = FORMS[String(d.formId)];
  if (!formCfg) { ignore('form_not_configured'); continue; }
  const submissionId = d.formSubmissionId ? String(d.formSubmissionId) : null;
  if (!submissionId) { ignore('missing_submission_id'); continue; }
  const key = `${b.eventType}:${submissionId}`;
  if (seenThisRun.has(key) || ledgerStore[key]) { ignore('duplicate_submission'); continue; }
  seenThisRun.add(key);

  const answers = (Array.isArray(d.answers) ? d.answers : []).flatMap((a) => normalizeAnswer(a));
  const submittedMs = toMs(d.submissionTimestamp) || toMs(b.eventTimestamp) || nowMs;
  out.push({
    json: {
      ...base,
      kind: 'event',
      authMethod: auth.method,
      ledgerKey: key,
      event: {
        requestId: b.requestId || null,
        eventType: b.eventType,
        formId: String(d.formId),
        submissionId,
        entryNum: d.entryNum ?? null,
        submittedAt: new Date(submittedMs).toISOString(),
        startedAt: toMs(d.submissionStartTimestamp) ? new Date(toMs(d.submissionStartTimestamp)).toISOString() : null,
        timezone: d.submissionTimezone || null,
        submittingUserId: d.submittingUserId != null ? String(d.submittingUserId) : null,
        isAnonymous: !!d.isAnonymous,
        managerFieldCount: Array.isArray(d.managerFields) ? d.managerFields.length : 0,
      },
      formConfig: { kind: 'job_completion', advance: false, ...formCfg },
      answers,
    },
  });
}
return out;

// ─────────────────────────────────────────────────────────────────────
// Node: Load Sandbox Lookups                 Mode: Run Once for Each Item
// Fictional form definition + submitter, in the same shape the live
// Connecteam Forms/Users API capture nodes produce.
// ─────────────────────────────────────────────────────────────────────
const item = $json;
const fx = item.sandboxFixtures || {};
const form = (fx.formDefinitions || {})[item.event.formId] || null;
const user = (fx.users || {})[item.event.submittingUserId] || null;
return {
  json: {
    ...item,
    formLookup: form ? { ok: true, source: 'sandbox', formName: form.formName, questions: form.questions } : { ok: false, source: 'sandbox', reason: 'no fixture form definition' },
    userLookup: user ? { ok: true, source: 'sandbox', firstName: user.firstName, lastName: user.lastName } : { ok: false, source: 'sandbox', reason: 'no fixture user' },
  },
};

// ─────────────────────────────────────────────────────────────────────
// Node: Capture Form Definition              Mode: Run Once for Each Item
// GET /forms/v1/forms/{formId} gives the form name and question titles,
// which the webhook payload doesn't include. A failed lookup keeps the sync
// going with question IDs as labels.
// ─────────────────────────────────────────────────────────────────────
const ctx = $('Sandbox Lookups?').item.json;
const res = $json || {};
const ok = Number(res.statusCode) === 200 && res.body;
const data = ok ? (res.body.data && (res.body.data.form || (Array.isArray(res.body.data.forms) ? res.body.data.forms[0] : res.body.data))) || res.body : null;
return {
  json: {
    ...ctx,
    formLookup: ok && data
      ? { ok: true, source: 'connecteam_api', formName: data.formName || data.name || null, questions: Array.isArray(data.questions) ? data.questions : [] }
      : { ok: false, source: 'connecteam_api', reason: `form lookup returned ${res.statusCode || 'network error'}` },
  },
};

// ─────────────────────────────────────────────────────────────────────
// Node: Capture Submitter                    Mode: Run Once for Each Item
// Resolves the submitting user's display name (first name + last initial
// only). Phone numbers and emails of field staff are never copied.
// ─────────────────────────────────────────────────────────────────────
const ctx = $('Capture Form Definition').item.json;
const res = $json || {};
const ok = Number(res.statusCode) === 200 && res.body;
const users = ok && res.body.data ? res.body.data.users || res.body.data.results || [] : [];
const u = Array.isArray(users) ? users.find((x) => String(x.userId ?? x.id) === String(ctx.event.submittingUserId)) || null : null;
return {
  json: {
    ...ctx,
    userLookup: u ? { ok: true, source: 'connecteam_api', firstName: u.firstName || null, lastName: u.lastName || null } : { ok: false, source: 'connecteam_api', reason: `user lookup returned ${res.statusCode || 'network error'}` },
  },
};

// ─────────────────────────────────────────────────────────────────────
// Node: Build Checklist Record               Mode: Run Once for Each Item
// • Labels answers with question titles
// • Evaluates the checklist (required items, safety-critical items, photos)
// • Extracts the deal-matching keys: job number, site address, customer phone
// • Builds the HTML note and the three HubSpot deal searches
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const PIPELINE = env('HUBSPOT_PIPELINE_ID', 'default');
const MATCHABLE = csv('HUBSPOT_MATCHABLE_STAGE_IDS', 'YOUR_SCHEDULED_STAGE_ID,YOUR_IN_PROGRESS_STAGE_ID,YOUR_READY_FOR_INVOICING_STAGE_ID');
const JOB_PROP = env('HUBSPOT_JOB_ID_PROPERTY', 'field_job_number');
const ADDR_PROP = env('HUBSPOT_ADDRESS_PROPERTY', 'field_site_address');
const COUNTRY_CODE = env('DEFAULT_COUNTRY_CALLING_CODE', '1').replace(/\D/g, '') || '1';
const INCLUDE_MEDIA_LINKS = flag('NOTE_INCLUDE_MEDIA_LINKS', true);
const INCLUDE_EMPTY = flag('NOTE_INCLUDE_EMPTY_ANSWERS', false);
const DISPLAY_TZ = env('DISPLAY_TIMEZONE', '');
const STATUS_PROPS = ['field_checklist_status', 'field_last_checklist_type', 'field_last_checklist_at', 'connecteam_last_submission_id'];

const item = $json;
const cfg = item.formConfig;
const ev = item.event;

// ── Titles ─────────────────────────────────────────────────────────────
const titles = {};
const walk = (qs) => {
  for (const q of qs || []) {
    if (!q) continue;
    const id = String(q.questionId ?? q.id ?? '');
    const t = q.title ?? q.questionTitle ?? q.text ?? q.name ?? q.label;
    if (id && t) titles[id] = String(t).slice(0, 200);
    walk(q.questions || q.subQuestions || q.groupQuestions);
  }
};
walk(item.formLookup && item.formLookup.questions);
const answers = item.answers.map((a) => ({ ...a, title: titles[a.questionId] || (cfg.questionTitles && cfg.questionTitles[a.questionId]) || `Question ${a.questionId}` }));
const byId = Object.fromEntries(answers.map((a) => [a.questionId, a]));

// ── Evaluation ────────────────────────────────────────────────────────
const checkable = answers.filter((a) => (a.questionType === 'yesNo' || a.questionType === 'task') && !a.hidden);
const requiredIds = Array.isArray(cfg.requiredPositiveQuestionIds) && cfg.requiredPositiveQuestionIds.length ? cfg.requiredPositiveQuestionIds.map(String) : checkable.map((a) => a.questionId);
const safetyIds = (cfg.safetyCriticalQuestionIds || []).map(String);
const failed = requiredIds.filter((id) => !safetyIds.includes(id)).map((id) => byId[id] || { questionId: id, title: titles[id] || `Question ${id}`, value: null, positive: null })
  .filter((a) => a.positive !== true).map((a) => ({ questionId: a.questionId, title: a.title, value: a.value || 'not answered' }));
const safetyIssues = safetyIds.map((id) => byId[id]).filter((a) => a && a.positive === false).map((a) => ({ questionId: a.questionId, title: a.title, value: a.value }));
const media = answers.flatMap((a) => a.media.map((m) => ({ ...m, question: a.title })));
const photoCount = media.filter((m) => m.kind === 'photo' || m.kind === 'scan').length;
const signatureCaptured = media.some((m) => m.kind === 'signature');
const minPhotos = Math.max(0, Number(cfg.minPhotos ?? 0));
const issues = [];
if (failed.length) issues.push(`${failed.length} required item(s) not confirmed`);
if (photoCount < minPhotos) issues.push(`${photoCount} of ${minPhotos} required photos`);
if (cfg.requireSignature && !signatureCaptured) issues.push('customer signature missing');
if (safetyIssues.length) issues.push(`${safetyIssues.length} safety-critical item(s) answered No`);
const status = safetyIssues.length ? 'safety_issue' : issues.length ? 'issues' : 'passed';

// ── Matching keys ─────────────────────────────────────────────────────
const val = (id) => (id && byId[String(id)] && byId[String(id)].value) || null;
const jobId = val(cfg.jobIdQuestionId) ? String(val(cfg.jobIdQuestionId)).trim().toUpperCase().slice(0, 60) : null;
const address = val(cfg.addressQuestionId);
const phoneRaw = val(cfg.phoneQuestionId);
const toE164 = (v) => {
  if (!v) return null;
  const s = String(v).trim(); const d = s.replace(/\D/g, '');
  if (s.startsWith('+') && d.length >= 8 && d.length <= 15) return `+${d}`;
  if (COUNTRY_CODE === '1' && d.length === 10) return `+1${d}`;
  if (COUNTRY_CODE === '1' && d.length === 11 && d.startsWith('1')) return `+${d}`;
  return d.length >= 8 && d.length <= 15 ? `+${d}` : null;
};
const phone = toE164(phoneRaw);
const ABBR = { street: 'st', drive: 'dr', road: 'rd', avenue: 'ave', court: 'ct', lane: 'ln', boulevard: 'blvd', place: 'pl', terrace: 'ter', highway: 'hwy', parkway: 'pkwy', circle: 'cir', north: 'n', south: 's', east: 'e', west: 'w', apartment: 'apt', suite: 'ste', unit: 'unit' };
const normAddr = (s) => String(s || '').toLowerCase().replace(/[.,#]/g, ' ').split(/\s+/).filter(Boolean).map((t) => ABBR[t] || t).join(' ');
const addrNorm = address ? normAddr(address) : null;
const addrTokens = addrNorm ? addrNorm.split(' ') : [];
const streetNumber = addrTokens.find((t) => /^\d+[a-z]?$/.test(t)) || null;
const isName = (t) => /^[a-z]{3,}$/.test(t) && !Object.values(ABBR).includes(t);
const afterNumber = streetNumber ? addrTokens.slice(addrTokens.indexOf(streetNumber) + 1).find(isName) : null;
const nameToken = afterNumber || addrTokens.filter((t) => /^[a-z]{3,}$/.test(t) && !Object.values(ABBR).includes(t)).sort((a, b) => b.length - a.length)[0] || null;

const stageFilters = [{ propertyName: 'pipeline', operator: 'EQ', value: PIPELINE }, { propertyName: 'dealstage', operator: 'IN', values: MATCHABLE }];
const props = ['dealname', 'dealstage', 'pipeline', 'hubspot_owner_id', JOB_PROP, ADDR_PROP, ...STATUS_PROPS];
const noop = { filterGroups: [{ filters: [{ propertyName: 'hs_object_id', operator: 'EQ', value: '0' }] }], limit: 1 };
const searches = {
  byJobId: jobId ? { filterGroups: [{ filters: [{ propertyName: JOB_PROP, operator: 'EQ', value: jobId }, ...stageFilters] }], properties: props, limit: 5 } : noop,
  byAddress: nameToken ? { filterGroups: [{ filters: [{ propertyName: ADDR_PROP, operator: 'CONTAINS_TOKEN', value: nameToken }, ...stageFilters] }], properties: props, limit: 20 } : noop,
  contactByPhone: phone ? { filterGroups: [
    { filters: [{ propertyName: 'phone', operator: 'EQ', value: phone }] },
    { filters: [{ propertyName: 'mobilephone', operator: 'EQ', value: phone }] },
    { filters: [{ propertyName: 'hs_searchable_calculated_phone_number', operator: 'EQ', value: phone.replace(/\D/g, '').slice(-10) }] }], properties: ['phone'], limit: 3 } : noop,
  dealsByContactTemplate: { stageFilters, properties: props, limit: 10 },
  noop,
};

// ── Note HTML ─────────────────────────────────────────────────────────
const html = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const tz = DISPLAY_TZ || ev.timezone || 'UTC';
const fmt = (iso) => { try { return new Intl.DateTimeFormat('en-GB', { timeZone: tz, dateStyle: 'medium', timeStyle: 'short' }).format(new Date(iso)); } catch (e) { return iso; } };
const KIND_LABEL = { pre_start: 'Pre-start checklist', safety: 'Safety checklist', job_completion: 'Job-completion checklist' };
const STATUS_LABEL = { passed: '✅ PASSED', issues: '⚠️ ISSUES FOUND', safety_issue: '🛑 SAFETY ISSUE' };
const submitter = item.userLookup && item.userLookup.ok ? `${item.userLookup.firstName || ''} ${item.userLookup.lastName ? item.userLookup.lastName[0] + '.' : ''}`.trim() : ev.isAnonymous ? 'Anonymous' : `User ${ev.submittingUserId || 'unknown'}`;
const formName = (item.formLookup && item.formLookup.formName) || cfg.label || `Form ${ev.formId}`;
const rows = answers.filter((a) => !a.hidden && (INCLUDE_EMPTY || (a.value !== null && !a.empty)) && a.media.length === 0)
  .map((a) => `<tr><td>${html(a.path ? a.path.replace(/\//g, ' › ') : '')}${html(a.title)}</td><td>${a.positive === false ? '<b>' : ''}${html(a.value ?? '—')}${a.positive === false ? '</b>' : ''}${a.hasLocation ? ' 📍' : ''}</td></tr>`);
const mediaLines = media.map((m) => {
  if (m.kind === 'signature') return `<li>✍️ Signature captured (${html(m.question)})</li>`;
  const label = `${m.kind === 'photo' ? '📷' : m.kind === 'video' ? '🎥' : m.kind === 'audio' ? '🎙️' : m.kind === 'scan' ? '🧾' : '📎'} ${html(m.question)} · ${html(m.name)}`;
  return INCLUDE_MEDIA_LINKS && /^https:\/\//.test(m.url) ? `<li><a href="${html(m.url)}">${label}</a></li>` : `<li>${label}</li>`;
});
let noteBody = `<p><b>${html(KIND_LABEL[cfg.kind] || 'Field checklist')}: ${html(formName)}</b> · ${STATUS_LABEL[status]}</p>`;
