// ─────────────────────────────────────────────────────────────────────
// Node: Resolve Deal Match                   Mode: Run Once for Each Item
// Scores every candidate deal from the three searches:
//   job number exact match   100
//   site address match       50 + 40 × token similarity (street number must match)
//   contact phone match      60
//   +10 for each additional source that agrees
// Matched only when the best score ≥ MIN_MATCH_SCORE and it leads the
// runner-up by ≥ AMBIGUITY_MARGIN. Ties are never auto-resolved.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
