};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const MIN_SCORE = num('MIN_MATCH_SCORE', 60);
const MARGIN = num('AMBIGUITY_MARGIN', 15);
