} else {
  ctx = $('Build Checklist Record').item.json;
  const contactStep = $('Build Contact Deal Search').item.json;
  res = {
    byJobId: $('Search Deals by Job Number').item.json,
    byAddress: $('Search Deals by Site Address').item.json,
    contactByPhone: { statusCode: contactStep.contactSearchStatus, body: { total: contactStep.contactCount, results: contactStep.contactId ? [{ id: contactStep.contactId }] : [] } },
    byContact: $json,
  };
}
const k = ctx.keys;
const JOB = ctx.hubspot.jobProperty;
const ADDR = ctx.hubspot.addressProperty;
const searchErrors = [];
const results = (name, r, wasUsed) => {
  if (!wasUsed) return [];
  if (Number(r && r.statusCode) !== 200 || !r.body || !Array.isArray(r.body.results)) { searchErrors.push(`${name}: ${(r && r.statusCode) || 'network error'}`); return []; }
  return r.body.results;
};

const ABBR = { street: 'st', drive: 'dr', road: 'rd', avenue: 'ave', court: 'ct', lane: 'ln', boulevard: 'blvd', place: 'pl', terrace: 'ter', highway: 'hwy', parkway: 'pkwy', circle: 'cir', north: 'n', south: 's', east: 'e', west: 'w', apartment: 'apt', suite: 'ste' };
