const cands = {};
const add = (deal, source, score, detail) => {
  const c = (cands[deal.id] = cands[deal.id] || { id: String(deal.id), properties: deal.properties || {}, sources: [], best: 0, detail: [] });
  if (!c.sources.includes(source)) c.sources.push(source);
  c.best = Math.max(c.best, score);
  c.detail.push(detail);
};
for (const d of results('job number search', res.byJobId, !!k.jobId)) {
  if (String((d.properties || {})[JOB] || '').trim().toUpperCase() === k.jobId) add(d, 'job_number', 100, `job ${k.jobId}`);
}
for (const d of results('address search', res.byAddress, !!k.nameToken)) {
  const tokens = normAddr((d.properties || {})[ADDR]);
  if (!k.streetNumber || !tokens.includes(k.streetNumber)) continue;
  const sim = similarity(k.addressNorm.split(' '), tokens);
