const current = m.deal ? m.deal.stage : null;

const holds = [];
if (!cfg.advance) holds.push(`${cfg.kind} checklists don't advance the stage`);
else {
  if (item.event.eventType !== 'form_submission') holds.push('edited submissions never advance the stage');
  if (item.checklist.status !== 'passed') holds.push(`checklist ${item.checklist.status.replace('_', ' ')}: ${item.checklist.issues.join('; ')}`);
